      "corporateLesson": {
        "en": "Just leaders treat all equally.",
        "hi": "न्यायप्रिय नेता सभी को समान अवसर देता है।"
      },
      "genZPerspective": {
        "en": "No bias – only balance.",
        "hi": "नो बायस – ऑनली बैलेंस।"
      },
      "mood": [
        "Peaceful",
        "Reflective"
      ]
