// Helper function to check if a shloka is part of a consolidated group
export function isConsolidatedShloka(chapter, verse) {
  const chapterConsolidations = CONSOLIDATED_SHLOKAS[chapter];
  if (!chapterConsolidations) return null;

  for (const group of chapterConsolidations) {
    if (group.verses.includes(verse)) {
      return group;
    }
  }
  return null;
}

// Helper function to get shloka display ID
export function getShlokaId(chapter, verse) {
  const consolidation = isConsolidatedShloka(chapter, verse);
  if (consolidation) {
    if (consolidation.verses[0] === verse) {
      return consolidation.id;
    }
    return null;
  }
  return `${chapter}.${verse}`;
}

// Get all displayable shlokas for a chapter
export function getChapterShlokas(chapter) {
  const chapterData = GITA_DATA[chapter];
  if (!chapterData) return [];

  const shlokas = [];
  const verses = Object.keys(chapterData).map(v => parseInt(v)).sort((a, b) => a - b);

  verses.forEach(verse => {
    const shlokaId = getShlokaId(chapter, verse);
    if (shlokaId) {
      const consolidation = isConsolidatedShloka(chapter, verse);
      shlokas.push({
        id: shlokaId,
        chapter,
        verse,
        isConsolidated: !!consolidation,
        consolidatedVerses: consolidation?.verses || [verse],
        data: chapterData[verse],
      });
    }
  });

  return shlokas;
}

// Search shlokas by theme
export function searchByTheme(theme) {
  const results = [];
  Object.keys(GITA_DATA).forEach((chapter) => {
    Object.keys(GITA_DATA[chapter]).forEach((verse) => {
      const shloka = GITA_DATA[chapter][verse];
      if (shloka.themes?.includes(theme)) {
        const shlokaId = getShlokaId(parseInt(chapter), parseInt(verse));
        if (shlokaId) {
          results.push({
            id: shlokaId,
            chapter: parseInt(chapter),
            verse: parseInt(verse),
            data: shloka,
          });
        }
      }
    });
  });
  return results;
}

// Search shlokas by mood
export function searchByMood(mood) {
  const results = [];
  Object.keys(GITA_DATA).forEach((chapter) => {
    Object.keys(GITA_DATA[chapter]).forEach((verse) => {
      const shloka = GITA_DATA[chapter][verse];
      if (shloka.mood?.includes(mood)) {
        const shlokaId = getShlokaId(parseInt(chapter), parseInt(verse));
        if (shlokaId) {
          results.push({
            id: shlokaId,
            chapter: parseInt(chapter),
            verse: parseInt(verse),
            data: shloka,
          });
        }
      }
    });
  });
  return results;
}

